// ── What dart:ui exposes ────────────────────────
// import 'dart:ui' as ui;
// final builder = ui.SceneBuilder()..pushOpacity(128);
// Most app code never touches dart:ui directly — the framework wraps it. But
// CustomPainter reaches it through Canvas, and dart:ffi sits beside it.

Future<void> main() async {
  // Must come first: everything below talks to the engine
  final binding = WidgetsFlutterBinding.ensureInitialized();
  binding.deferFirstFrame();                 // hold the native splash

  await SystemChrome.setPreferredOrientations([DeviceOrientation.portraitUp]);
  await Firebase.initializeApp();            // platform channel
  final prefs = await SharedPreferences.getInstance();
  final config = await rootBundle.loadString('assets/config.json');

  // App lifecycle without a widget in sight
  binding.addObserver(_LifecycleLogger());

  runApp(App(prefs: prefs, config: jsonDecode(config)));
  binding.allowFirstFrame();
}

class _LifecycleLogger extends WidgetsBindingObserver {
  @override
  void didChangeAppLifecycleState(AppLifecycleState state) => debugPrint('$state');
}

