class RenderStripe extends RenderBox with RenderObjectWithChildMixin<RenderBox> {
  RenderStripe({required double thickness}) : _thickness = thickness;

  double _thickness;
  set thickness(double v) {
    if (v == _thickness) return;
    _thickness = v;
    markNeedsLayout();          // walks up only to the nearest boundary
  }

  // Size depends on the constraints alone → this object is a relayout boundary
  @override
  bool get sizedByParent => true;

  @override
  void performResize() {
    size = constraints.biggest;
  }

  @override
  void performLayout() {
    final child = this.child;
    if (child == null) return;
    // ✅ we do not read child.size, so the child becomes a boundary too
    child.layout(BoxConstraints.tight(Size(size.width, _thickness)));
    // If we needed the measurement we would have to opt in and give that up:
    // child.layout(constraints.loosen(), parentUsesSize: true);
  }

  @override
  void paint(PaintingContext context, Offset offset) {
    if (child != null) context.paintChild(child!, offset);
  }
}

