class MeasuredHeader extends StatefulWidget {
  const MeasuredHeader({super.key});
  @override State<MeasuredHeader> createState() => _MeasuredHeaderState();
}

class _MeasuredHeaderState extends State<MeasuredHeader> {
  final _key = GlobalKey();
  double? _height;

  @override
  void initState() {
    super.initState();
    // Layout has not run yet — size is only knowable after the frame
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;                       // may fire after dispose
      final box = _key.currentContext!.findRenderObject() as RenderBox;
      setState(() => _height = box.size.height);  // safe: frame is over
    });
  }

  @override
  Widget build(BuildContext context) => Column(key: _key, children: [
        const Text('Header'),
        if (_height != null) Text('measured ${_height!.toStringAsFixed(1)}'),
      ]);
}

// Transient callback: a Ticker driving a value every frame
class _Spinner extends State<Spinner> with SingleTickerProviderStateMixin {
  late final Ticker _ticker = createTicker((elapsed) {
    setState(() => _angle = elapsed.inMilliseconds / 1000 * 2 * pi);
  })..start();
  double _angle = 0;
  @override void dispose() { _ticker.dispose(); super.dispose(); }
  @override Widget build(BuildContext c) => Transform.rotate(angle: _angle,
      child: const Icon(Icons.refresh));
}

